import{_ as n,C as s,o as e,c as h,j as i,E as l,a as o,a3 as r}from"./chunks/framework.C6R8kWFE.js";const j=JSON.parse(`{"title":"2-dars (Mentor). Business Intelligence (BI) asoslari: Katta to'rtlik va hayotiy sikl","description":"","frontmatter":{"title":"2-dars (Mentor). Business Intelligence (BI) asoslari: Katta to'rtlik va hayotiy sikl","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (BI)","link":"/mentor/9-sinf-bi/"},"week":{"n":1,"link":"/mentor/9-sinf-bi/hafta-01/"},"g":2,"title":"Business Intelligence (BI) asoslari: Katta to'rtlik va hayotiy sikl","lead":"Ma'lumotlarni strategik kuchga aylantiring: zamonaviy Business Intelligence arxitekturasi, tahlilning Katta to'rtligi va qaror qabul qilish sikli bilan tanishing.","slide":"/slaydlar/9-sinf-bi/hafta-01/dars-2.html","test":"/slaydlar/9-sinf-bi/hafta-01/dars-2-test.html","student_link":"/9-sinf-bi/hafta-01/dars-2","tabs":[{"g":1,"link":"/mentor/9-sinf-bi/hafta-01/dars-1","current":false},{"g":2,"link":"/mentor/9-sinf-bi/hafta-01/dars-2","current":true},{"g":3,"link":"/mentor/9-sinf-bi/hafta-01/dars-3","current":false}],"prev":{"g":1,"title":"Ma’lumot tushunchasi, uning turlari va DIKW modeli","link":"/mentor/9-sinf-bi/hafta-01/dars-1"},"next":{"g":3,"title":"BI tizimlari turlari, mutaxassislik rollari va Excel analitik platformasi","link":"/mentor/9-sinf-bi/hafta-01/dars-3"}}},"headers":[],"relativePath":"mentor/9-sinf-bi/hafta-01/dars-2.md","filePath":"mentor/9-sinf-bi/hafta-01/dars-2.md"}`),m={name:"mentor/9-sinf-bi/hafta-01/dars-2.md"},u={class:"blk"},d={id:"dars-rejasi",tabindex:"-1"},g={class:"blk"},k={id:"mentor-konspekti",tabindex:"-1"},b={class:"blk"},q={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},y={class:"blk"},v={id:"tezkor-nazorat-savollari",tabindex:"-1"},c={class:"blk"},f={id:"uyga-vazifa",tabindex:"-1"};function p(z,a,_,x,T,I){const t=s("Icon");return e(),h("div",null,[i("div",u,[i("h2",d,[l(t,{name:"file-text"}),a[0]||(a[0]=o(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga Business Intelligence (BI) mohiyati, zamonaviy biznesdagi vazifalari, tahlilning &quot;Katta to&#39;rtligi&quot; (Deskriptiv, Diagnostik, Prediktiv, Preskriptiv), BI ekotizimining 5 ta tayanch komponenti hamda BI ning 6 bosqichli hayotiy siklini tushuntirish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar BI nima ekanini va an&#39;anaviy hisobotdan qanday farqlanishini biladi; Katta to&#39;rtlik tahlil turlarini real keyslar orqali ajrata oladi; ETL va Data Warehouse tushunchalarini tizimli tushunadi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan mavzuni takrorlash (DIKW): 10 daqiqa</li><li>Yangi mavzu: BI ta&#39;rifi va Katta to&#39;rtlik: 25 daqiqa</li><li>BI komponentlari va hayotiy sikli: 20 daqiqa</li><li>Amaliy mashg&#39;ulot (Keys tahlili): 15 daqiqa</li><li>Tezkor savol-javob va xulosa: 10 daqiqa</li></ul></li></ul><hr>",2))]),i("div",g,[i("h2",k,[l(t,{name:"file-text"}),a[3]||(a[3]=o(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=r('<h3 id="_1-business-intelligence-bi-nima" tabindex="-1">1. Business Intelligence (BI) nima? <a class="header-anchor" href="#_1-business-intelligence-bi-nima" aria-label="Permalink to &quot;1. Business Intelligence (BI) nima?&quot;">​</a></h3><p>Business Intelligence (BI) — bu tashkilotlarda ma’lumotlarni yig‘ish, tizimlashtirish, qayta ishlash, tahlil qilish va vizuallashtirish orqali to‘g‘ri, tez va strategik qarorlar qabul qilishni qo‘llab-quvvatlovchi texnologiyalar, metodlar va jarayonlar majmuasidir. BI ning asosiy vazifasi: $$\\text{Xom Ma&#39;lumot} \\longrightarrow \\text{Axborot} \\longrightarrow \\text{Tahliliy Tushuncha (Insight)} \\longrightarrow \\text{Boshqaruv Qarori}$$ zanjirini avtomatlashtirishdan iborat.</p><h3 id="_2-tahlilning-katta-to-rtligi-the-bi-s-big-four" tabindex="-1">2. Tahlilning &quot;Katta to&#39;rtligi&quot; (The BI’s Big Four) <a class="header-anchor" href="#_2-tahlilning-katta-to-rtligi-the-bi-s-big-four" aria-label="Permalink to &quot;2. Tahlilning &quot;Katta to&#39;rtligi&quot; (The BI’s Big Four)&quot;">​</a></h3><p>Rasmiy darslikka ko&#39;ra, biznes tahlili murakkablik va biznesga keltiradigan qiymat darajasiga qarab 4 toifaga bo&#39;linadi:</p><ol><li><strong>Tavsifiy (Deskriptiv) tahlil:</strong> <em>&quot;O‘tmishda nima sodir bo‘ldi?&quot;</em><ul><li>O&#39;tgan davrdagi sotuvlar, mijozlar soni, foyda va xarajatlarni umumlashtiradi.</li><li>Vositalar: oylik va yillik hisobotlar, KPI panellari.</li></ul></li><li><strong>Diagnostik tahlil:</strong> <em>&quot;Nima uchun sodir bo‘ldi?&quot;</em><ul><li>Anomaliyalar, savdo pasayishi yoki oshishi sabablarini (root causes) aniqlaydi.</li><li>Vositalar: detallarga chuqur kirish (drill-down), korrelyatsiya tahlili, ma&#39;lumotlarni qidirish (Data Mining).</li></ul></li><li><strong>Bashoratli (Prediktiv) tahlil:</strong> <em>&quot;Kelajakda nima sodir bo‘lishi mumkin?&quot;</em><ul><li>Tarixiy ma&#39;lumotlarga tayanib, kelajakdagi trendlar, ehtimollar va talab darajasini oldindan aytadi.</li><li>Vositalar: statistik modellar, regressiya tahlili, Machine Learning algoritmlari.</li></ul></li><li><strong>Retseptiv (Preskriptiv) tahlil:</strong> <em>&quot;Eng yaxshi natijaga erishish uchun nima qilish kerak?&quot;</em><ul><li>Tahlil piramidasining eng yuqori pog&#39;onasi. Eng maqbul harakat yo&#39;nalishini tavsiya etadi.</li><li>Vositalar: optimallashtirish algoritmlari, avtomatlashtirilgan qaror qabul qilish tizimlari (masalan, narxlarni dinamik boshqarish).</li></ul></li></ol><h3 id="_3-bi-ekotizimining-5-ta-asosiy-komponenti" tabindex="-1">3. BI ekotizimining 5 ta asosiy komponenti <a class="header-anchor" href="#_3-bi-ekotizimining-5-ta-asosiy-komponenti" aria-label="Permalink to &quot;3. BI ekotizimining 5 ta asosiy komponenti&quot;">​</a></h3><ol><li><strong>Ma’lumot manbalari (Data Sources):</strong> Ichki tizimlar (CRM, ERP, POS), tashqi manbalar va sensorlar.</li><li><strong>ETL jarayoni (Extract, Transform, Load):</strong> Ma&#39;lumotlarni turli manbalardan yig&#39;ish (Extract), tozalash va standartlashtirish (Transform), omborga yuklash (Load).</li><li><strong>Ma’lumotlar ombori (Data Warehouse / Data Mart):</strong> Tahlil uchun maxsus optimallashtirilgan, yagona ishonchli markaziy baza (Single Source of Truth).</li><li><strong>Semantik qatlam (Semantic Layer):</strong> Murakkab kodlarni biznesga tushunarli ko&#39;rsatkichlarga (KPI, sof foyda, konversiya) aylantiruvchi ko&#39;prik.</li><li><strong>Vizuallashtirish vositalari (Visualization Tools):</strong> Power BI, Tableau, interaktiv dashboardlar orqali natijalarni ko&#39;rsatish.</li></ol><h3 id="_4-bi-tizimining-hayotiy-sikli-6-bosqich" tabindex="-1">4. BI tizimining hayotiy sikli (6 bosqich) <a class="header-anchor" href="#_4-bi-tizimining-hayotiy-sikli-6-bosqich" aria-label="Permalink to &quot;4. BI tizimining hayotiy sikli (6 bosqich)&quot;">​</a></h3><p><code>Talablarni aniqlash</code> $\\to$ <code>Ma&#39;lumotlarni yig&#39;ish</code> $\\to$ <code>Tahlil va modellashtirish</code> $\\to$ <code>Hisobot (Reporting)</code> $\\to$ <code>Harakat (Acting)</code> $\\to$ <code>Takrorlash (Iteration)</code>.</p><hr>',10))]),i("div",b,[i("h2",q,[l(t,{name:"file-text"}),a[6]||(a[6]=o(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=r('<h3 id="_1-topshiriq-tahlil-turlarini-aniqlash-oson" tabindex="-1">1-topshiriq. Tahlil turlarini aniqlash (oson) <a class="header-anchor" href="#_1-topshiriq-tahlil-turlarini-aniqlash-oson" aria-label="Permalink to &quot;1-topshiriq. Tahlil turlarini aniqlash (oson)&quot;">​</a></h3><p>Quyidagi vaziyatlar Katta to&#39;rtlikning qaysi turiga kirishini aniqlang:</p><ol><li>&quot;Kompaniyamiz o&#39;tgan oyda 120 mln so&#39;mlik mahsulot sotdi&quot;.</li><li>&quot;Sotuvlarning 15% ga pasayishiga asosiy raqobatchining 20% lik chegirma e&#39;lon qilgani sabab bo&#39;lgan&quot;.</li><li>&quot;Kelasi oyda maktab formalariga talab 4 barobarga oshishi kutilmoqda&quot;.</li><li>&quot;Ombordagi xarajatlarni 10% kamaytirish uchun har hafta 200 qutidan buyurtma berish optimal hisoblanadi&quot;.</li></ol><p><strong>Yechim:</strong></p><ol><li>Tavsifiy (Deskriptiv) — o&#39;tmishda nima bo&#39;lganini ko&#39;rsatadi.</li><li>Diagnostik — hodisaning &quot;nima uchun?&quot; yuz bergan sababini aniqlaydi.</li><li>Bashoratli (Prediktiv) — kelajakdagi talabni taxmin qiladi.</li><li>Retseptiv (Preskriptiv) — maqsadga erishish uchun eng yaxshi yechimni tavsiya qiladi.</li></ol><h3 id="_2-topshiriq-etl-jarayoni-ketma-ketligi-o-rta" tabindex="-1">2-topshiriq. ETL jarayoni ketma-ketligi (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-etl-jarayoni-ketma-ketligi-o-rta" aria-label="Permalink to &quot;2-topshiriq. ETL jarayoni ketma-ketligi (o&#39;rta)&quot;">​</a></h3><p>Onlayn do&#39;konga tegishli quyidagi amallarni ETL ning 3 ta bosqichiga ajrating:</p><ul><li>A: PostgreSQL bazasiga tozalangan buyurtmalar jadvalini joylashtirish.</li><li>B: Telegram bot, veb-sayt va Instagram xabarlaridan mijoz ma&#39;lumotlarini yuklab olish.</li><li>C: Telefon raqamlarni yagona <code>+998...</code> formatiga keltirish, dublikat ismlarni o&#39;chirish va bo&#39;sh kataklarni to&#39;ldirish.</li></ul><p><strong>Yechim:</strong></p><ul><li>Extract (Olish): B (turli manbalardan yig&#39;ish).</li><li>Transform (O&#39;zgartirish): C (formatlash, tozalash, dublikatlarni o&#39;chirish).</li><li>Load (Yuklash): A (markaziy omborga yuklash).</li></ul><h3 id="_3-topshiriq-supermarket-uchun-bi-arxitekturasini-loyihalash-qiyin" tabindex="-1">3-topshiriq. Supermarket uchun BI arxitekturasini loyihalash (qiyin) <a class="header-anchor" href="#_3-topshiriq-supermarket-uchun-bi-arxitekturasini-loyihalash-qiyin" aria-label="Permalink to &quot;3-topshiriq. Supermarket uchun BI arxitekturasini loyihalash (qiyin)&quot;">​</a></h3><p>Yirik supermarketlar tarmog&#39;i mahsulotlarning yaroqlilik muddatini nazorat qilish va muddati o&#39;tayotgan tovarlar bo&#39;yicha yo&#39;qotishlarni kamaytirmoqchi. Ushbu muammoni hal qilish uchun Katta to&#39;rtlikning barcha 4 ta tahlil turini o&#39;z ichiga olgan reja tuzing.</p><p><strong>Yechim:</strong></p><ol><li><em>Tavsifiy:</em> O&#39;tgan chorakda muddati o&#39;tib ketgani sababli hisobdan chiqarilgan tovarlar ro&#39;yxati va ularning umumiy zarari hisoblanadi.</li><li><em>Diagnostik:</em> Nima sababdan ushbu tovarlar sotilmay qolgani o&#39;rganiladi (narx qimmatmidi, peshtaxtaning ko&#39;rinmas burchagidami yoki ortiqcha xarid qilinganmi?).</li><li><em>Bashoratli:</em> Har bir tovar toifasining kunlik sotilish tezligiga qarab, kelasi 10 kun ichida qaysi mahsulotlarning muddati o&#39;tib ketish xavfi yuqoriligi prognoz qilinadi.</li><li><em>Retseptiv:</em> Tizim avtomatik ravishda yaroqlilik muddati tugashiga 3 kun qolgan tovarlarga 30% lik chegirma (sariq narx belgisi) belgilashni va ularni markaziy peshtaxtaga ko&#39;chirishni tavsiya qiladi.</li></ol><hr>',15))]),i("div",y,[i("h2",v,[l(t,{name:"file-text"}),a[9]||(a[9]=o(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=r("<ol><li>Deskriptiv va Diagnostik tahlil o&#39;rtasidagi asosiy farq nima? <ul><li><em>Javob:</em> Deskriptiv tahlil &quot;Nima bo&#39;ldi?&quot; savoliga, Diagnostik esa &quot;Nima uchun bo&#39;ldi?&quot; savoliga javob beradi.</li></ul></li><li>ETL qisqartmasi nimani anglatadi va uning eng murakkab bosqichi qaysi? <ul><li><em>Javob:</em> Extract, Transform, Load. Eng ko&#39;p vaqt va mehnat talab qiladigan bosqich — Transform (ma&#39;lumotlarni tozalash va standartlashtirish).</li></ul></li><li>Data Warehouse nima uchun kundalik operatsion bazalardan alohida saqlanadi? <ul><li><em>Javob:</em> Chunki kundalik savdo tizimi sekinlashib qolmasligi va tarixiy tahlillar uchun yaxlit yagona manba yaratish uchun.</li></ul></li></ol><hr>",2))]),i("div",c,[i("h2",f,[l(t,{name:"house"}),a[12]||(a[12]=o(" Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=i("p",null,"O'zingiz tanlagan biror biznes (masalan, kofe do'koni, avtomobil yuvish shoxobchasi yoki xususiy klinika) uchun Katta to'rtlikning har bir turiga mos 1 tadan hayotiy misol tuzing (jami 4 ta jumla).",-1))])])}const P=n(m,[["render",p]]);export{j as __pageData,P as default};
